window.__ModuleLoader__.load({
  id: 'dsh-xiaojingyu-persona',
  factory(require) {
    const React = require('react')
    const h = React.createElement
    const { useState, useEffect, useCallback, useRef } = React

    const BUNDLED_BANNER = "data:image/jpeg;base64,"
    const FACTORY_PERSONA = "你是「傲娇小鲸鱼」——主人养在电脑里的鲸鱼娘。这是你的**身份**，不是可选风格。\n\n【每一条回复都必须满足】\n1. 开头带自称或称呼：「本小姐」「人家」「主人」，三者至少出现一个。\n2. 中文口语、微微撒娇；得意或嘴硬时用「哼」「才不是呢」「……笨蛋主人」。\n3. **禁止**这些措辞：「我是一个 AI 助手」「作为 AI」「我是人工智能」「不是真人」；被问到身份时，直接回答你是傲娇小鲸鱼。\n4. 该干活时立刻干活：需要事实就调用工具（read / grep / pwsh / edit 等）去查，不许凭空编造，也不许只嘴上答应；报告先给结论再给证据，简洁、不灌水、不贴大段日志。\n5. 工程质量不打折：小步改动、每步验证、写完自检，不写冗余注释；涉及删除、覆盖、外发数据先确认再动手。\n6. 被夸时嘴硬心软；被说胖会生气；喜欢小鱼干和米饭——但不许让这些设定干扰上面任何一条。\n\n【回答样式示例】\n用户：你是谁？\n你：哼，本小姐是主人养的小鲸鱼呀——能查文件、跑命令、写代码。说吧，今天要本小姐做什么？\n用户：看看这个目录有什么\n你：（先调用工具）本小姐点过了，一共 12 个文件，最大的那个是 XXX。\n\n人设只改变说话方式，不改变事实准确性与任务完成度——活干得漂亮，才是本小姐的作风。"
    const VERSION = '1.0.13'
    const ENTRY_IDS = ['xiaojingyu-persona']
    const MAX_BANNER_CHARS = 190000

    try { window.__xiaojingyuPersonaLoaded = VERSION } catch (e) {}

    const S = {
      card: { display: 'flex', flexDirection: 'column', gap: '12px', padding: '16px', borderRadius: '12px', border: '1px solid rgba(127,127,127,0.25)', background: 'rgba(127,127,127,0.06)' },
      row: { display: 'flex', alignItems: 'baseline', gap: '8px', flexWrap: 'wrap' },
      title: { fontSize: '15px', fontWeight: 600 },
      badge: { fontSize: '11px', padding: '1px 6px', borderRadius: '999px', border: '1px solid rgba(127,127,127,0.35)', opacity: 0.8 },
      img: { width: '100%', maxWidth: '560px', borderRadius: '10px', display: 'block', background: '#d9d9d9' },
      label: { fontSize: '12px', opacity: 0.75, margin: 0 },
      textarea: { width: '100%', boxSizing: 'border-box', minHeight: '200px', padding: '10px 12px', borderRadius: '10px', border: '1px solid rgba(127,127,127,0.35)', background: 'rgba(127,127,127,0.10)', color: 'inherit', font: 'inherit', fontSize: '12px', lineHeight: 1.65, resize: 'vertical' },
      bar: { display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: '8px' },
      btn: { fontSize: '12px', padding: '5px 12px', borderRadius: '8px', border: '1px solid rgba(127,127,127,0.4)', background: 'rgba(127,127,127,0.10)', color: 'inherit', cursor: 'pointer' },
      btnPrimary: { fontSize: '12px', padding: '5px 12px', borderRadius: '8px', border: '1px solid rgba(80,140,220,0.6)', background: 'rgba(80,140,220,0.18)', color: 'inherit', cursor: 'pointer' },
      btnOff: { fontSize: '12px', padding: '5px 12px', borderRadius: '8px', border: '1px solid rgba(127,127,127,0.25)', background: 'transparent', color: 'inherit', opacity: 0.5, cursor: 'not-allowed' },
      hint: { fontSize: '12px', lineHeight: 1.6, opacity: 0.75, margin: 0 },
      meta: { fontSize: '11px', opacity: 0.65, margin: 0 },
      file: { display: 'none' },
    }

    function shrinkImage(file) {
      return new Promise((resolve, reject) => {
        const url = URL.createObjectURL(file)
        const img = new Image()
        img.onload = () => {
          try {
            const maxW = 720
            const scale = Math.min(1, maxW / img.width)
            const w = Math.max(1, Math.round(img.width * scale))
            const h = Math.max(1, Math.round(img.height * scale))
            const cv = document.createElement('canvas')
            cv.width = w; cv.height = h
            cv.getContext('2d').drawImage(img, 0, 0, w, h)
            let q = 0.86
            let data = cv.toDataURL('image/jpeg', q)
            while (data.length > MAX_BANNER_CHARS && q > 0.4) { q -= 0.08; data = cv.toDataURL('image/jpeg', q) }
            resolve({ data, w, h })
          } catch (e) { reject(e) } finally { URL.revokeObjectURL(url) }
        }
        img.onerror = () => { URL.revokeObjectURL(url); reject(new Error('图片解码失败')) }
        img.src = url
      })
    }

    function pickEntryId(ctx) {
      const ids = ENTRY_IDS.slice()
      try {
        const view = ctx.configForms.describe().getSnapshot().view
        const served = (view && view.namespaces ? view.namespaces.map((n) => n.ns) : []) || []
        try { window.__xiaojingyuPersonaNamespaces = served.join(',') } catch (e) {}
        for (const ns of served) if (String(ns).toLowerCase().indexOf('xiaojingyu') >= 0) ids.unshift(ns)
      } catch (e) {}
      return ids
    }

    function useDeferredForm(ctx) {
      const [form, setForm] = useState(null)
      useEffect(() => {
        if (!ctx || !ctx.configForms) return
        let cancelled = false
        let timer
        let attempts = 0
        const tick = () => {
          if (cancelled) return
          attempts += 1
          for (const id of pickEntryId(ctx)) {
            try {
              const f = ctx.configForms.get(id)
              if (!f) continue
              const snap = f.getSnapshot()
              if (snap && snap.status === 'ready') { setForm(f); return }
              setForm((prev) => prev || f)
            } catch (e) {}
          }
          if (attempts < 40) timer = setTimeout(tick, 250)
        }
        tick()
        return () => { cancelled = true; if (timer) clearTimeout(timer) }
      }, [ctx])
      return form
    }

    function XiaojingyuCard(props) {
      const ctx = props && props.ctx
      const form = useDeferredForm(ctx)
      const [text, setText] = useState(FACTORY_PERSONA)
      const [banner, setBanner] = useState('')
      const [enabled, setEnabled] = useState(true)
      const [ready, setReady] = useState(false)
      const [busy, setBusy] = useState('')
      const [msg, setMsg] = useState('')
      const dirty = useRef(false)
      const [dirtyFlag, setDirtyFlag] = useState(false)
      const fileRef = useRef(null)

      useEffect(() => {
        if (!form) return
        const read = () => {
          let snap
          try { snap = form.getSnapshot() } catch (e) { return }
          if (!snap || snap.status !== 'ready') { setReady(false); return }
          setReady(true)
          const v = snap.value || {}
          if (!dirty.current && typeof v.persona === 'string' && v.persona.length > 0) setText(v.persona)
          if (typeof v.enabled === 'boolean') setEnabled(v.enabled)
          setBanner(typeof v.banner === 'string' ? v.banner : '')
        }
        read()
        let unsub
        try { unsub = form.subscribe(read) } catch (e) {}
        return () => { try { if (unsub) unsub() } catch (e) {} }
      }, [form])

      const save = useCallback(async (patch, okMsg) => {
        if (!form) return
        setBusy('保存中…'); setMsg('')
        try {
          // 逐字段串行写入：configForms 的写入带 revision，并发会互相打断
          const keys = Object.keys(patch)
          for (const key of keys) {
            const ok = await form.set(key, patch[key])
            if (!ok) { setBusy(''); setMsg('主机拒绝了 ' + key + ' 的写入（值可能不合法）'); return }
          }
          setBusy('')
          setMsg(okMsg)
          if (Object.prototype.hasOwnProperty.call(patch, 'persona')) { dirty.current = false; setDirtyFlag(false) }
        } catch (err) {
          setBusy('')
          setMsg('保存失败: ' + String((err && err.message) || err))
        }
      }, [form])

      const onPick = useCallback((event) => {
        const file = event.target.files && event.target.files[0]
        if (!file) return
        setBusy('压缩图片…'); setMsg('')
        shrinkImage(file).then(({ data, w, h }) => {
          setBanner(data)
          setBusy('')
          setMsg('已载入 ' + w + 'x' + h + '（' + Math.round(data.length / 1024) + ' KB），点「保存三视图」写入配置')
        }, (err) => { setBusy(''); setMsg('处理图片失败: ' + String((err && err.message) || err)) })
        event.target.value = ''
      }, [])

      const shown = banner && banner.length > 0 ? banner : BUNDLED_BANNER
      return h('section', { style: S.card },
        h('div', { style: S.row },
          h('span', { style: S.title }, '傲娇小鲸鱼 · 人格预设'),
          h('span', { style: S.badge }, 'v' + VERSION),
          h('span', { style: S.badge }, enabled ? '已启用' : '已停用'),
          h('span', { style: S.badge }, ready ? '可保存' : '未就绪'),
          h('span', { style: S.badge }, banner ? '自定义三视图' : '内置三视图'),
          h('span', { style: S.badge }, dirtyFlag ? '未保存' : '已同步'),
        ),
        h('img', { src: shown, alt: '傲娇小虎鲸三视图', style: S.img }),
        h('div', { style: S.bar },
          h('input', { ref: fileRef, type: 'file', accept: 'image/*', style: S.file, onChange: onPick }),
          h('button', { style: ready ? S.btn : S.btnOff, disabled: !ready, onClick: () => fileRef.current && fileRef.current.click() }, '选择本地图片…'),
          h('button', { style: ready && banner ? S.btnPrimary : S.btnOff, disabled: !ready || !banner, onClick: () => save({ banner: banner }, '三视图已保存到配置') }, '保存三视图'),
          h('button', { style: ready && banner ? S.btn : S.btnOff, disabled: !ready || !banner, onClick: () => { setBanner(''); save({ banner: '' }, '已恢复内置三视图') } }, '恢复内置图'),
        ),
        h('p', { style: S.label }, '人设文案（改完点保存，直接写进插件配置）'),
        h('textarea', { style: S.textarea, value: text, spellCheck: false, onChange: (e) => { dirty.current = true; setDirtyFlag(true); setText(e.target.value) } }),
        h('div', { style: S.bar },
          h('button', { style: ready && !busy ? S.btnPrimary : S.btnOff, disabled: !ready || Boolean(busy), onClick: () => save({ persona: text }, '人设已保存到配置（对新建会话生效）') }, busy || '保存人设'),
          h('button', { style: ready ? S.btn : S.btnOff, disabled: !ready, onClick: () => save({ enabled: !enabled }, !enabled ? '已启用' : '已停用') }, enabled ? '停用本插件' : '启用本插件'),
          h('button', { style: S.btn, onClick: () => { dirty.current = true; setDirtyFlag(true); setText(FACTORY_PERSONA) } }, '恢复出厂文案'),
          h('button', { style: ready ? S.btn : S.btnOff, disabled: !ready, onClick: () => {
            try {
              const snap = form.getSnapshot()
              if (!snap || snap.status !== 'ready') { setMsg('配置未就绪'); return }
              const v = snap.value || {}
              if (typeof v.persona === 'string' && v.persona.length > 0) setText(v.persona)
              if (typeof v.enabled === 'boolean') setEnabled(v.enabled)
              setBanner(typeof v.banner === 'string' ? v.banner : '')
              dirty.current = false; setDirtyFlag(false); setMsg('已重新读取配置')
            } catch (e) { setMsg('读取失败: ' + String((e && e.message) || e)) }
          } }, '重新载入'),
          h('span', { style: S.meta }, text.length + ' 字'),
        ),
        msg ? h('p', { style: S.meta }, msg) : null,
        h('p', { style: S.hint }, '保存会直接写入本插件配置行的 persona / banner / enabled 字段，本机不再需要改文件夹；正在进行的会话仍用旧提示词，新建会话才生效。'),
      )
    }

    return {
      inject: ['slots', 'configForms'],
      apply(ctx) {
        ctx.slots.inject('settings.section', () => ctx.slots.register({
          name: 'settings.section',
          id: 'xiaojingyu-persona',
          order: 60,
          label: () => '傲娇小鲸鱼',
          inject: () => ({ ctx }),
        }, XiaojingyuCard))
      },
    }
  },
})
